/**
 * The signed-in user's own notes (archived included, shared-with-me excluded) as a download:
 * JSON by default or with `?format=json`, CSV with `?format=csv`.
 */
const CSV_COLUMNS = ['number', 'title', 'body', 'pinned', 'archived', 'createdAt'] as const

type ExportedNote = {
  number: number
  title: string
  body: string
  pinned: boolean
  archived: boolean
  createdAt: string
}

/** Quotes a value only when it holds a comma, a double quote or a line break; inner quotes are doubled. */
function csvValue(value: string | number | boolean): string {
  const text = String(value)
  return /[",\r\n]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text
}

export default defineEventHandler((event) => {
  const name = currentUser(event)
  if (!name) throw createError({ statusCode: 401, statusMessage: 'Not signed in' })
  const format = getQuery(event).format
  if (format !== undefined && format !== 'json' && format !== 'csv') {
    throw createError({ statusCode: 400, statusMessage: 'Unknown export format' })
  }
  const notes: ExportedNote[] = listOwnNotes(name).map((note) => ({
    number: note.number,
    title: note.title,
    body: (note.body ?? '').replace(/\r\n?/g, '\n'),
    pinned: note.pinned,
    archived: note.archived,
    createdAt: new Date(note.createdAt).toISOString(),
  }))
  if (format === 'csv') {
    setResponseHeader(event, 'content-type', 'text/csv; charset=utf-8')
    setResponseHeader(event, 'content-disposition', `attachment; filename="notes-${name}.csv"`)
    const lines = [CSV_COLUMNS.join(','), ...notes.map((note) => CSV_COLUMNS.map((column) => csvValue(note[column])).join(','))]
    return lines.map((line) => `${line}\r\n`).join('')
  }
  setResponseHeader(event, 'content-type', 'application/json')
  setResponseHeader(event, 'content-disposition', `attachment; filename="notes-${name}.json"`)
  return { user: name, notes }
})
